fn init_bash(no_cmd: bool, cmd: String, hook: Hook) -> Result<(), Box<dyn std::error::Error>> {
    let hook_str = match hook {
        Hook::None => "none".to_string(),
        Hook::Prompt => "prompt".to_string(),
        Hook::Pwd => "pwd".to_string(),
    };

    let output = format!(
        r#");# =============================================================================
#
# zoxide bash init
#
# To initialize zoxide, add this to your configuration (usually ~/.bashrc):
#
# eval "$(zoxide init bash)"
#
# =============================================================================

__zoxide_bin() {
    command -v zoxide >/dev/null 2>&1 && command -v zoxide || echo "zoxide"
}

__zoxide_hook() {
    local pwd="$PWD"
    if [[ -n "$_ZO_RESOLVE_SYMLINKS" ]]; then
        pwd=$(readlink -f "$pwd")
    fi
    __zoxide_bin add -- "$pwd"
}

__zoxide_z() {
    if [[ $# -eq 0 ]]; then
        cd ~
    elif [[ $# -eq 1 && "$1" == "-" ]]; then
        cd -
    elif [[ -d "$1" ]]; then
        cd "$1"
    else
        local result
        result=$(__zoxide_bin query --exclude "$PWD" -- "$@")
        cd "$result"
    fi
}

__zoxide_zi() {
    local result
    result=$(__zoxide_bin query -i -- "$@")
    cd "$result"
}

